DO $$ BEGIN CREATE TYPE public.assignment_status AS ENUM ('active','pending','ended','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.compliance_action_type AS ENUM ('WARN','RESTRICT','SUSPEND','DEACTIVATE','REINSTATE','NOTIFY'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.crm_doc_class AS ENUM ('master','customer_instance'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.crm_doc_external_state AS ENUM ('draft','approved','shared','customer_review','customer_revision_requested','revised','accepted','executed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.crm_doc_internal_state AS ENUM ('draft','internal_review','approval_pending','approved','active','superseded','archived'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.doc_verification_status AS ENUM ('not_submitted','pending','in_review','approved','rejected','resubmission_required','expired'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.fleet_entity_type AS ENUM ('HOLDING','COMPANY','BRANCH'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.health_status AS ENUM ('HEALTHY','DEGRADED','DOWN','UNKNOWN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.incident_severity AS ENUM ('low','medium','high','critical'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.infra_check_result AS ENUM ('PASS','FAIL','BLOCKED','UNKNOWN','NOT_CONFIGURED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.infra_job_state AS ENUM ('REQUESTED','RUNNING','SUCCEEDED','FAILED','BLOCKED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.inspection_result AS ENUM ('pass','conditional','fail','pending'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.insurance_status AS ENUM ('ACTIVE','EXPIRED','CANCELLED','PENDING','CLAIM'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.lifecycle_stage AS ENUM ('APPLICANT','SCREENING','KYC','TRAINING','VEHICLE_ASSIGNMENT', 'ACTIVATION','ACTIVE','PERFORMANCE_REVIEW','REWARDED', 'WARNED','RESTRICTED','SUSPENDED','REACTIVATED','RETIRED','REJECTED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.loan_status AS ENUM ('REQUESTED','APPROVED','DISBURSED','REPAYING','COMPLETED','DEFAULTED','REJECTED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.air_aircraft_classes ( code text PRIMARY KEY, label text NOT NULL, example_models text NOT NULL, seats int NOT NULL, cruise_kts int NOT NULL, benchmark_hourly_usd numeric NOT NULL, min_block_hours numeric NOT NULL DEFAULT 1, bush_strip_ok boolean NOT NULL DEFAULT false, sort int NOT NULL DEFAULT 100 );
CREATE TABLE IF NOT EXISTS public.air_airfields ( code text PRIMARY KEY, name text NOT NULL, city text NOT NULL, country text NOT NULL DEFAULT 'Kenya', kind text NOT NULL DEFAULT 'airport', lat double precision NOT NULL, lng double precision NOT NULL, landing_fee_kes numeric NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, sort int NOT NULL DEFAULT 100 );
CREATE TABLE IF NOT EXISTS public.charter_partner_applications ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, submitted_by UUID, operator_name TEXT NOT NULL, contact_name TEXT NOT NULL, contact_email TEXT NOT NULL, contact_phone TEXT, country TEXT, home_base TEXT, fleet_size INTEGER NOT NULL DEFAULT 0, aircraft_types TEXT, aoc_number TEXT, insurance_expiry DATE, notes TEXT, documents JSONB NOT NULL DEFAULT '[]'::jsonb, status TEXT NOT NULL DEFAULT 'submitted', reviewer_id UUID, review_note TEXT, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT charter_partner_applications_status_chk CHECK (status IN ('submitted','under_review','documents_required','approved','rejected')) );
CREATE TABLE IF NOT EXISTS public.commercial_rate_cards ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, name text NOT NULL, product_domain text NOT NULL CHECK (product_domain IN ( 'ride_hailing','corporate_charter','delivery','logistics','rentals','leasing','other')), version text NOT NULL, status text NOT NULL DEFAULT 'source' CHECK (status IN ('source','pending_approval','approved','retired')), currency text NOT NULL DEFAULT 'KES', effective_from date, review_at date, source_note text, source_reference text, owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, created_by uuid, approved_by uuid, approved_at timestamptz, retired_at timestamptz, change_reason text, provenance text NOT NULL DEFAULT 'LIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.commercial_signals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), signal_key text NOT NULL, signal_type text NOT NULL, source text NOT NULL, entity_type text NOT NULL, entity_id uuid, account_id uuid, customer_label text, severity text NOT NULL DEFAULT 'info' CHECK (severity IN ('info','low','medium','high','critical')), urgency text NOT NULL DEFAULT 'normal' CHECK (urgency IN ('whenever','normal','today','now')), commercial_impact_cents bigint, customer_impact text, headline text NOT NULL, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, recommended_action text, owner_user_id uuid, status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','actioned','dismissed','expired')), status_note text, status_by uuid, status_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, UNIQUE (signal_key) );
CREATE TABLE IF NOT EXISTS public.commercial_vehicle_categories ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, label text NOT NULL, product_domain text NOT NULL DEFAULT 'corporate_charter', example_models text[] NOT NULL DEFAULT '{}', accessibility boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.countries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), iso2 text UNIQUE NOT NULL, iso3 text UNIQUE NOT NULL, name text NOT NULL, currency text NOT NULL DEFAULT 'KES', phone_code text, timezone text DEFAULT 'Africa/Nairobi', is_active boolean NOT NULL DEFAULT true, launched_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.crm_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_ref text NOT NULL UNIQUE DEFAULT ('ACC-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), name text NOT NULL, legal_name text, industry text, country text NOT NULL DEFAULT 'KE', city text, size_band text NOT NULL DEFAULT 'unknown' CHECK (size_band IN ('unknown','micro','small','mid','large','enterprise')), lifecycle_stage text NOT NULL DEFAULT 'prospect' CHECK (lifecycle_stage IN ('prospect','engaged','qualified','opportunity','negotiation','won','onboarding','active','expansion','renewal','lost')), importance_tier text NOT NULL DEFAULT 'standard' CHECK (importance_tier IN ('standard','key','strategic')), owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, corporate_id uuid REFERENCES public.corporate_accounts(id) ON DELETE SET NULL, source text NOT NULL DEFAULT 'outbound', website text, notes text, provenance text NOT NULL DEFAULT 'declared', seed_batch text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.delivery_dispatch_jobs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid REFERENCES public.packages(id) ON DELETE CASCADE, order_id uuid REFERENCES public.delivery_orders(id) ON DELETE CASCADE, module text NOT NULL, status text NOT NULL DEFAULT 'queued', priority integer NOT NULL DEFAULT 5, sla_deadline timestamptz, required_vehicle_type text, required_capacity_kg numeric(8,3), origin_lat numeric(10,7), origin_lng numeric(10,7), destination_lat numeric(10,7), destination_lng numeric(10,7), attempts integer NOT NULL DEFAULT 0, last_attempt_at timestamptz, assigned_driver_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.delivery_driver_scores ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, module text NOT NULL, acceptance_rate numeric(5,4), on_time_rate numeric(5,4), cancel_rate numeric(5,4), rating numeric(3,2), completed_deliveries integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (driver_id, module, window_start, window_end) );
CREATE TABLE IF NOT EXISTS public.driver_achievement_progress ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL, current_tier TEXT NOT NULL DEFAULT 'Bronze', points INTEGER NOT NULL DEFAULT 0, trips_30d INTEGER NOT NULL DEFAULT 0, rating_30d NUMERIC(3,2) NOT NULL DEFAULT 0, acceptance_30d NUMERIC(5,2) NOT NULL DEFAULT 0, cancellation_30d NUMERIC(5,2) NOT NULL DEFAULT 0, last_unlock_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (driver_id) );
CREATE TABLE IF NOT EXISTS public.driver_achievement_tiers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tier text NOT NULL UNIQUE, sort_order int NOT NULL, min_trips int NOT NULL DEFAULT 0, min_rating numeric(3,2) NOT NULL DEFAULT 0, min_acceptance_rate numeric(4,3) NOT NULL DEFAULT 0, max_cancellation_rate numeric(4,3) NOT NULL DEFAULT 1, commission_discount_pct numeric(4,3) NOT NULL DEFAULT 0, weekly_bonus_kes numeric(10,2) NOT NULL DEFAULT 0, perks jsonb NOT NULL DEFAULT '[]'::jsonb, badge_color text NOT NULL DEFAULT '#6b7280', description text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_analytics_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, session_id TEXT, event_name TEXT NOT NULL, page_route TEXT, funnel_stage TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_application_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.driver_applications(id) ON DELETE CASCADE, doc_code text NOT NULL, doc_label text NOT NULL, is_mandatory boolean NOT NULL DEFAULT true, state text NOT NULL DEFAULT 'MISSING' CHECK (state IN ('MISSING','PENDING_REVIEW','VERIFIED','REJECTED','EXPIRED')), storage_path text, document_number text, issuing_authority text, issued_on date, expires_on date, review_notes text, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at timestamptz, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (application_id, doc_code) );
CREATE TABLE IF NOT EXISTS public.driver_application_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.driver_applications(id) ON DELETE CASCADE, action text NOT NULL, status_from text, status_to text, note text, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_benefits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, benefit_type text NOT NULL, provider text, status text NOT NULL DEFAULT 'ACTIVE', start_date date, end_date date, amount_cents bigint, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.driver_compliance ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID UNIQUE REFERENCES public.drivers(id) ON DELETE CASCADE, compliance_score NUMERIC(5,2) DEFAULT 0, license_valid BOOLEAN DEFAULT false, badge_valid BOOLEAN DEFAULT false, background_check_valid BOOLEAN DEFAULT false, insurance_valid BOOLEAN DEFAULT false, inspection_valid BOOLEAN DEFAULT false, overall_status TEXT DEFAULT 'non_compliant', next_review_date DATE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_compliance_scores ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL REFERENCES public.drivers(id) ON DELETE CASCADE, driver_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, overall_score NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (overall_score BETWEEN 0 AND 100), documents_score NUMERIC(5,2) DEFAULT 0, freshness_score NUMERIC(5,2) DEFAULT 0, training_score NUMERIC(5,2) DEFAULT 0, incident_score NUMERIC(5,2) DEFAULT 0, rating_score NUMERIC(5,2) DEFAULT 0, verification_score NUMERIC(5,2) DEFAULT 0, band TEXT GENERATED ALWAYS AS ( CASE WHEN overall_score >= 80 THEN 'green' WHEN overall_score >= 50 THEN 'yellow' ELSE 'red' END ) STORED, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (driver_id) );
CREATE TABLE IF NOT EXISTS public.driver_courses ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, duration_minutes INT NOT NULL DEFAULT 30, is_certification BOOLEAN NOT NULL DEFAULT false, is_required BOOLEAN NOT NULL DEFAULT false, is_published BOOLEAN NOT NULL DEFAULT true, sort_order INT NOT NULL DEFAULT 100, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_daily_metrics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, metric_date date NOT NULL, trips_count int DEFAULT 0, gross_cents bigint DEFAULT 0, net_cents bigint DEFAULT 0, online_minutes int DEFAULT 0, acceptance_rate numeric(5,2), cancellation_rate numeric(5,2), rating_avg numeric(3,2), incidents_count int DEFAULT 0, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(driver_id, metric_date) );
CREATE TABLE IF NOT EXISTS public.driver_documents ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, doc_type TEXT NOT NULL CHECK (doc_type IN ( 'NATIONAL_ID','PASSPORT','SELFIE','DRIVING_LICENSE','PSV_LICENSE', 'VEHICLE_LOGBOOK','VEHICLE_INSPECTION','VEHICLE_INSURANCE', 'GOOD_CONDUCT','KRA_PIN','OTHER' )), file_url TEXT NOT NULL, file_name TEXT, status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED','EXPIRED')), rejection_reason TEXT, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_earnings_models ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), city TEXT NOT NULL, vehicle_type TEXT NOT NULL, hourly_average_cents BIGINT NOT NULL CHECK (hourly_average_cents >= 0), surge_multiplier NUMERIC(4,2) NOT NULL DEFAULT 1.00 CHECK (surge_multiplier >= 0), incentive_per_week_cents BIGINT NOT NULL DEFAULT 0 CHECK (incentive_per_week_cents >= 0), currency TEXT NOT NULL DEFAULT 'KES', is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (city, vehicle_type) );
CREATE TABLE IF NOT EXISTS public.driver_etims_failures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.driver_etims_invoices(id) ON DELETE CASCADE, error_code text, error_message text NOT NULL, payload jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_etims_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, kra_pin text NOT NULL, etims_branch_id text, device_serial text, registered boolean NOT NULL DEFAULT false, registered_at timestamptz, consent_given_at timestamptz, consent_revoked_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_etims_retries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.driver_etims_invoices(id) ON DELETE CASCADE, attempt_count int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'PENDING', last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_etims_submissions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.driver_etims_invoices(id) ON DELETE CASCADE, attempt_no int NOT NULL, request_payload jsonb, response_payload jsonb, http_status int, succeeded boolean NOT NULL DEFAULT false, submitted_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_etims_sync_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.driver_etims_invoices(id) ON DELETE CASCADE, event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_financial_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, credit_score numeric(5,2), savings_score numeric(5,2), income_stability numeric(5,2), loan_repayment numeric(5,2), overall numeric(5,2), computed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.driver_housing_levy ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, gross_cents bigint NOT NULL DEFAULT 0, employee_levy_cents bigint NOT NULL DEFAULT 0, employer_levy_cents bigint NOT NULL DEFAULT 0, total_levy_cents bigint GENERATED ALWAYS AS (employee_levy_cents + employer_levy_cents) STORED, status public.driver_tax_liability_status NOT NULL DEFAULT 'OPEN', liability_id uuid REFERENCES public.driver_tax_liabilities(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (driver_id, period_start, period_end) );
CREATE TABLE IF NOT EXISTS public.driver_incidents ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID REFERENCES public.drivers(id) ON DELETE SET NULL, vehicle_id UUID REFERENCES public.vehicles(id) ON DELETE SET NULL, incident_type TEXT NOT NULL, severity incident_severity NOT NULL DEFAULT 'low', description TEXT, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), reported_by UUID, status TEXT NOT NULL DEFAULT 'open', resolution TEXT, resolved_at TIMESTAMPTZ, metadata JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_insurance ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, product text NOT NULL, provider text, policy_number text, status public.insurance_status NOT NULL DEFAULT 'PENDING', premium_cents bigint, coverage_cents bigint, starts_at date, ends_at date, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_lifecycle_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, action public.compliance_action_type NOT NULL, reason text, effective_from timestamptz NOT NULL DEFAULT now(), effective_until timestamptz, actor_id uuid, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_lifecycle_history ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, from_stage public.lifecycle_stage, to_stage public.lifecycle_stage NOT NULL, reason text, actor_id uuid, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_lifecycle_stages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, sort_order int NOT NULL, description text, is_terminal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_loans ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, principal_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', interest_rate_bps int NOT NULL DEFAULT 0, term_months int NOT NULL, outstanding_cents bigint NOT NULL, status public.loan_status NOT NULL DEFAULT 'REQUESTED', purpose text, disbursed_at timestamptz, due_at timestamptz, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_locations (driver_id uuid PRIMARY KEY, lat double precision NOT NULL, lng double precision NOT NULL, heading numeric(5,2), speed_kph numeric(5,2), accuracy_m numeric(6,2), is_online boolean NOT NULL DEFAULT false, is_available boolean NOT NULL DEFAULT false, vehicle_id uuid, battery_pct int, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.driver_onboarding_drafts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, current_stage INT NOT NULL DEFAULT 1 CHECK (current_stage BETWEEN 1 AND 7), status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SUBMITTED','APPROVED','REJECTED')), data JSONB NOT NULL DEFAULT '{}'::jsonb, submitted_at TIMESTAMPTZ, reviewed_at TIMESTAMPTZ, reviewer_id UUID REFERENCES auth.users(id), review_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_photos ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID REFERENCES public.drivers(id) ON DELETE CASCADE, photo_type TEXT NOT NULL, storage_url TEXT NOT NULL, face_match_score NUMERIC(5,2), verification_status doc_verification_status NOT NULL DEFAULT 'pending', uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_reputation ( driver_id uuid PRIMARY KEY, rating numeric(3,2) DEFAULT 5.00, trips_total int DEFAULT 0, reviews_count int DEFAULT 0, badges jsonb DEFAULT '[]'::jsonb, achievements jsonb DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_risk_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, rule_code text NOT NULL, severity public.risk_severity NOT NULL, score_delta numeric(5,2) NOT NULL DEFAULT 0, dimension text NOT NULL, details jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_risk_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid UNIQUE NOT NULL, compliance_score numeric(5,2) DEFAULT 100, safety_score numeric(5,2) DEFAULT 100, fraud_score numeric(5,2) DEFAULT 0, financial_score numeric(5,2) DEFAULT 100, operational_score numeric(5,2) DEFAULT 100, overall_risk public.risk_severity NOT NULL DEFAULT 'LOW', last_evaluated_at timestamptz, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_risk_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, dimension text NOT NULL, severity public.risk_severity NOT NULL, score_delta numeric(5,2) NOT NULL, active boolean NOT NULL DEFAULT true, config jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_savings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, balance_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', goal_cents bigint, goal_label text, interest_rate_bps int DEFAULT 0, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_scores ( driver_id uuid PRIMARY KEY, overall numeric(5,2) DEFAULT 100, compliance numeric(5,2) DEFAULT 100, safety numeric(5,2) DEFAULT 100, fraud numeric(5,2) DEFAULT 0, financial numeric(5,2) DEFAULT 100, performance numeric(5,2) DEFAULT 100, training numeric(5,2) DEFAULT 0, computed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_self_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL CHECK (kind IN ('income','expense')), category text NOT NULL DEFAULT 'other' CHECK (char_length(category) BETWEEN 1 AND 40), amount numeric(12,2) NOT NULL CHECK (amount > 0 AND amount < 10000000), entry_date date NOT NULL, note text CHECK (char_length(note) <= 500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_success_stories ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_name TEXT NOT NULL, city TEXT NOT NULL, vehicle_type TEXT, headline TEXT NOT NULL, body TEXT NOT NULL, monthly_earnings_cents BIGINT, trips_completed INT, rating NUMERIC(3,2), years_on_platform NUMERIC(4,1), avatar_url TEXT, is_published BOOLEAN NOT NULL DEFAULT true, published_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_trip_earnings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), earning_reference text NOT NULL UNIQUE, booking_id uuid NOT NULL UNIQUE REFERENCES public.trip_bookings(id), driver_id uuid NOT NULL REFERENCES public.drivers(id), driver_user_id uuid, carrier_id uuid REFERENCES public.carrier_profiles(id), service_line text NOT NULL, currency text NOT NULL DEFAULT 'KES', gross_cents bigint NOT NULL CHECK (gross_cents >= 0), commission_bps integer NOT NULL CHECK (commission_bps >= 0 AND commission_bps <= 10000), commission_cents bigint NOT NULL CHECK (commission_cents >= 0), deductions_cents bigint NOT NULL DEFAULT 0 CHECK (deductions_cents >= 0), net_cents bigint NOT NULL CHECK (net_cents >= 0), state text NOT NULL DEFAULT 'EARNED' CHECK (state IN ('PENDING','ELIGIBLE','EARNED','AVAILABLE','WITHDRAWN','PAID','REVERSED','DISPUTED')), data_class text NOT NULL DEFAULT 'PRODUCTION' CHECK (data_class IN ('PRODUCTION','TEST')), journal_id uuid, wallet_transaction_id uuid, payout_id uuid, terms_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, accrued_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_vehicle_assignments ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL REFERENCES public.drivers(id) ON DELETE CASCADE, vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, assignment_type TEXT NOT NULL DEFAULT 'primary', start_date DATE NOT NULL DEFAULT CURRENT_DATE, end_date DATE, status assignment_status NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_verifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, check_type TEXT NOT NULL CHECK (check_type IN ( 'IDENTITY','LICENSE','VEHICLE','BACKGROUND','BIOMETRIC','FRAUD' )), status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','PASSED','FAILED','MANUAL_REVIEW')), provider TEXT, provider_reference TEXT, details JSONB NOT NULL DEFAULT '{}'::jsonb, performed_by UUID REFERENCES auth.users(id), performed_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_withdrawal_certifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payout_id uuid NOT NULL, driver_user_id uuid, correlation_id text, passed boolean NOT NULL, score int NOT NULL, chain jsonb NOT NULL DEFAULT '{}'::jsonb, reconciliation jsonb NOT NULL DEFAULT '{}'::jsonb, failures jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fact_drivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, snapshot_date date NOT NULL, trips int NOT NULL DEFAULT 0, earnings_cents bigint NOT NULL DEFAULT 0, online_hours numeric(6,2), acceptance_rate numeric(5,4), cancellation_rate numeric(5,4), rating numeric(3,2), compliance_score numeric(5,2), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (driver_id, snapshot_date));
CREATE TABLE IF NOT EXISTS public.fleet_driver_licences ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES public.drivers(id) ON DELETE CASCADE, licence_number text NOT NULL, expiry_date date, issue_date date, file_url text, file_name text, status text NOT NULL DEFAULT 'PENDING', recorded_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fleets ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), fleet_code TEXT UNIQUE NOT NULL DEFAULT ('FLT-' || upper(substring(replace(gen_random_uuid()::text,'-',''),1,8))), name TEXT NOT NULL, owner_user_id UUID, country TEXT DEFAULT 'KE', city TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_provider_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_key text NOT NULL UNIQUE, environment_key text, category text NOT NULL, provider text, resource text NOT NULL, required_action text NOT NULL, required_permission text, configuration jsonb NOT NULL DEFAULT '{}'::jsonb, required_output text NOT NULL, register_where text NOT NULL, owner_role text NOT NULL DEFAULT 'platform_owner', expected_evidence text NOT NULL, dependent_controls text[] NOT NULL DEFAULT '{}', state public.infra_job_state NOT NULL DEFAULT 'REQUESTED', submitted_result jsonb, validation_result public.infra_check_result NOT NULL DEFAULT 'UNKNOWN', validation_detail text, resolved_at timestamptz, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_programmes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, description text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.kyc_document_types ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_name TEXT NOT NULL, document_code TEXT UNIQUE NOT NULL, description TEXT, country TEXT DEFAULT 'KE', driver_type driver_type, applies_to TEXT NOT NULL DEFAULT 'driver', required BOOLEAN NOT NULL DEFAULT true, expiry_required BOOLEAN NOT NULL DEFAULT false, verification_required BOOLEAN NOT NULL DEFAULT true, display_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_fleet_capacity ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL UNIQUE REFERENCES public.vehicles(id) ON DELETE CASCADE, vehicle_class text NOT NULL, payload_capacity_kg numeric(12,2) NOT NULL, volume_capacity_cbm numeric(12,3) NOT NULL DEFAULT 0, base_label text NOT NULL, base_lat numeric(9,6), base_lng numeric(9,6), operating_radius_km numeric(8,2) NOT NULL DEFAULT 150, capability_status text NOT NULL DEFAULT 'UNAVAILABLE', hazardous_certified boolean NOT NULL DEFAULT false, temperature_controlled boolean NOT NULL DEFAULT false, compliance_valid_until date, carrier_id uuid, notes text, registered_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fleet_cap_class CHECK (vehicle_class = ANY (ARRAY['TRUCK_3T','TRUCK_7T','TRUCK_14T','TRUCK_28T'])), CONSTRAINT fleet_cap_payload CHECK (payload_capacity_kg > 0 AND payload_capacity_kg <= 60000), CONSTRAINT fleet_cap_volume CHECK (volume_capacity_cbm >= 0), CONSTRAINT fleet_cap_radius CHECK (operating_radius_km > 0), CONSTRAINT fleet_cap_status CHECK (capability_status = ANY (ARRAY['AVAILABLE','RESERVED','DISPATCHED','IN_TRANSIT','MAINTENANCE','UNAVAILABLE','INACTIVE'])) );
CREATE TABLE IF NOT EXISTS public.logistics_message_providers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel text NOT NULL DEFAULT 'sms' CHECK (channel IN ('sms','whatsapp','email')), provider text NOT NULL, environment text NOT NULL DEFAULT 'production' CHECK (environment IN ('sandbox','staging','production')), credentials_secret_name text, sender_identity text, enabled boolean NOT NULL DEFAULT false, timeout_ms integer NOT NULL DEFAULT 10000 CHECK (timeout_ms BETWEEN 1000 AND 60000), retry_max_attempts integer NOT NULL DEFAULT 3 CHECK (retry_max_attempts BETWEEN 0 AND 10), retry_backoff_seconds integer NOT NULL DEFAULT 30, health_status text NOT NULL DEFAULT 'unknown' CHECK (health_status IN ('unknown','healthy','degraded','unavailable','configuration_required')), health_checked_at timestamptz, health_detail text, notes text, updated_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (channel, environment) );
CREATE TABLE IF NOT EXISTS public.logistics_route_providers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_key text NOT NULL UNIQUE, display_name text NOT NULL, enabled boolean NOT NULL DEFAULT false, base_url text, credential_secret_name text, config jsonb NOT NULL DEFAULT '{}'::jsonb, health_status text NOT NULL DEFAULT 'unknown' CHECK (health_status IN ('unknown','healthy','degraded','unreachable','unconfigured')), health_detail text, last_checked_at timestamptz, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_capacity ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_user_id uuid NOT NULL, provider_name text NOT NULL, provider_kind text NOT NULL CHECK (provider_kind IN ('DRIVER','FLEET_OPERATOR','CHARTER_OPERATOR','LOGISTICS_OPERATOR')), family text NOT NULL CHECK (family IN ('ride','charter','rental','logistics')), title text NOT NULL, vehicle_type text NOT NULL, spec text, seats integer CHECK (seats IS NULL OR seats >= 0), units integer NOT NULL DEFAULT 1 CHECK (units >= 1), base_city text NOT NULL, coverage_area text, rate_amount numeric(14,2) CHECK (rate_amount IS NULL OR rate_amount >= 0), rate_basis text NOT NULL DEFAULT 'per_day' CHECK (rate_basis IN ('per_trip','per_hour','per_day','per_km','per_tonne','on_request')), currency text NOT NULL DEFAULT 'KES', available_from date, available_to date, registration_ref text, notes text, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PENDING_APPROVAL','APPROVED','PUBLISHED','SENT_BACK','RETIRED')), submitted_at timestamptz, submitted_by uuid, decided_at timestamptz, decided_by uuid, decision_reason text, published_at timestamptz, retired_at timestamptz, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_user_id uuid NOT NULL, doc_kind text NOT NULL CHECK (doc_kind IN ('OPERATING_LICENCE','INSURANCE','VEHICLE_INSPECTION','IDENTIFICATION','TAX_COMPLIANCE')), title text, reference_no text, expires_on date, object_path text NOT NULL, file_name text, mime_type text, size_bytes bigint, status text NOT NULL DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED','VERIFIED','REJECTED','SUPERSEDED')), review_note text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_escalation_routes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, category text NOT NULL, label text NOT NULL, responsible_team text NOT NULL, response_minutes integer NOT NULL DEFAULT 60, blocks_booking boolean NOT NULL DEFAULT false, guidance text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_platform_postings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), posting_type text NOT NULL CHECK (posting_type IN ('COMMISSION','WITHDRAWAL_FEE')), provider_user_id uuid NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents >= 0), currency text NOT NULL DEFAULT 'KES', paybill text NOT NULL, rate_bps integer NOT NULL, source_kind text NOT NULL, source_id uuid, reference text NOT NULL UNIQUE, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_verification ( provider_user_id uuid PRIMARY KEY, state text NOT NULL DEFAULT 'UNVERIFIED' CHECK (state IN ('UNVERIFIED','IN_REVIEW','VERIFIED','SUSPENDED','BLOCKED')), reason text, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_verification_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_user_id uuid NOT NULL, from_state text, to_state text NOT NULL, reason text, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_candidates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_no text NOT NULL UNIQUE, full_name text NOT NULL, email text, phone text, location text, headline text, summary text, linkedin_url text, portfolio_url text, years_experience numeric, current_employer text, current_title text, source text NOT NULL DEFAULT 'careers_site', owner_recruiter_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, engagement_status text NOT NULL DEFAULT 'active' CHECK (engagement_status IN ('active','passive','unresponsive','withdrawn','hired','blocked')), consent_given boolean NOT NULL DEFAULT false, consent_at timestamptz, record_state text NOT NULL DEFAULT 'active' CHECK (record_state IN ('active','archived','locked','redacted')), last_contact_at timestamptz, next_action text, next_action_due date, user_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_letter_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_key text NOT NULL, version integer NOT NULL DEFAULT 1, comm_type text NOT NULL, title text NOT NULL, subject text NOT NULL, body_markdown text NOT NULL, variables text[] NOT NULL DEFAULT '{}', classification text NOT NULL DEFAULT 'confidential', watermark_text text NOT NULL DEFAULT 'YALLA MOBILITY', requires_approval boolean NOT NULL DEFAULT true, approver_roles text[] NOT NULL DEFAULT ARRAY['recruiter'], status text NOT NULL DEFAULT 'draft', content_hash text, created_by uuid DEFAULT auth.uid(), activated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_letter_templates_key_version UNIQUE (template_key, version), CONSTRAINT rec_letter_templates_status_chk CHECK (status IN ('draft','active','retired')), CONSTRAINT rec_letter_templates_class_chk CHECK (classification IN ('internal','confidential','strictly_confidential')), CONSTRAINT rec_letter_templates_type_chk CHECK (comm_type IN ( 'interview_invitation','reschedule_notice','interview_cancellation','regret', 'appointment_letter','offer_letter','onboarding_pack','preemployment_request')) );
CREATE TABLE IF NOT EXISTS public.rec_requisitions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requisition_no text NOT NULL UNIQUE, title text NOT NULL, unit_id uuid REFERENCES public.org_units(id) ON DELETE SET NULL, position_id uuid REFERENCES public.org_positions(id) ON DELETE SET NULL, requested_by_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, hiring_manager_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, headcount integer NOT NULL DEFAULT 1 CHECK (headcount > 0), is_replacement boolean NOT NULL DEFAULT false, employment_type text NOT NULL DEFAULT 'permanent', location text, justification text, budget_min_cents bigint, budget_max_cents bigint, currency text NOT NULL DEFAULT 'KES', priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','critical')), target_hire_date date, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','department_review','budget_review','approval','approved','recruitment_open','closed','cancelled')), submitted_at timestamptz, approved_at timestamptz, approved_by uuid, decision_notes text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_providers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, provider_type text NOT NULL DEFAULT 'THIRD_PARTY' CHECK (provider_type IN ('YALLA','THIRD_PARTY')), contact_email text, contact_phone text, kra_pin text, commission_pct numeric(5,2), settlement_terms text, status text NOT NULL DEFAULT 'ONBOARDING' CHECK (status IN ('ONBOARDING','ACTIVE','SUSPENDED','EXITED')), compliance_state text NOT NULL DEFAULT 'EVIDENCE_REQUIRED' CHECK (compliance_state IN ('EVIDENCE_REQUIRED','VERIFIED','EXPIRED')), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.service_provider_claim_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES public.service_provider_claims(id) ON DELETE CASCADE, action text NOT NULL, state_from text, state_to text, note text, actor_user_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_platforms ( slug text PRIMARY KEY, name text NOT NULL, icon_key text NOT NULL, hostnames text[] NOT NULL, purpose text NOT NULL, channel_kind text NOT NULL DEFAULT 'PROFILE' CHECK (channel_kind IN ('PROFILE','CONVERSATION')), enabled boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 100, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_accidents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, driver_id uuid, occurred_at timestamptz NOT NULL, severity public.risk_severity NOT NULL DEFAULT 'LOW', location text, latitude numeric(10,7), longitude numeric(10,7), description text, police_report_no text, insurance_claim_no text, estimated_cost_cents bigint, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, asset_tag text UNIQUE, purchase_price_cents bigint, current_value_cents bigint, depreciation_pct_annual numeric(5,2), finance_partner text, loan_balance_cents bigint, status text NOT NULL DEFAULT 'OWNED', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.vehicle_compliance ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid UNIQUE NOT NULL, compliance_score numeric(5,2) DEFAULT 100, inspection_score numeric(5,2) DEFAULT 100, insurance_score numeric(5,2) DEFAULT 100, roadworthiness_score numeric(5,2) DEFAULT 100, overall_risk public.risk_severity NOT NULL DEFAULT 'LOW', last_evaluated_at timestamptz, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_compliance_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, rule_code text NOT NULL, severity public.risk_severity NOT NULL, dimension text NOT NULL, score_delta numeric(5,2) NOT NULL DEFAULT 0, details jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_costs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, cost_type text NOT NULL, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', incurred_at timestamptz NOT NULL DEFAULT now(), reference_id uuid, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_inspections ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, inspection_date DATE NOT NULL, inspector_name TEXT, inspection_center TEXT, brakes_status TEXT, tires_status TEXT, lights_status TEXT, engine_status TEXT, interior_status TEXT, cleanliness_score INT, result inspection_result NOT NULL DEFAULT 'pending', next_inspection_date DATE, report_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_maintenance ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, category text NOT NULL, description text, performed_at timestamptz NOT NULL DEFAULT now(), next_due_at timestamptz, odometer_km int, cost_cents bigint DEFAULT 0, currency text DEFAULT 'KES', vendor text, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_ownership_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, owner_type text NOT NULL, owner_id uuid, owner_name text, from_date date NOT NULL, to_date date, transfer_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.vehicle_service_records ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, service_type text NOT NULL, performed_at timestamptz NOT NULL DEFAULT now(), odometer_km int, notes text, cost_cents bigint DEFAULT 0, attachments jsonb DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.air_fleet ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.charter_partner_applications(id) ON DELETE CASCADE, owner_id uuid NOT NULL DEFAULT auth.uid(), operator_name text NOT NULL, registration text NOT NULL, model text NOT NULL, class_code text NOT NULL REFERENCES public.air_aircraft_classes(code), seats int NOT NULL CHECK (seats BETWEEN 1 AND 30), home_base text NOT NULL REFERENCES public.air_airfields(code), hourly_rate_kes numeric NOT NULL CHECK (hourly_rate_kes > 0), year_built int, amenities text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended','rejected')), review_note text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (registration) );
CREATE TABLE IF NOT EXISTS public.capacity_enquiries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), capacity_id uuid NOT NULL REFERENCES public.provider_capacity(id) ON DELETE CASCADE, lead_ref text, requester_user_id uuid, organisation_name text, contact_name text, service_date date, passengers integer CHECK (passengers IS NULL OR passengers >= 0), requirement text, status text NOT NULL DEFAULT 'NEW' CHECK (status IN ('NEW','ACKNOWLEDGED','CLOSED')), provider_note text, acknowledged_at timestamptz, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.crm_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), doc_class public.crm_doc_class NOT NULL, doc_type text NOT NULL, title text NOT NULL, description text, account_id uuid REFERENCES public.crm_accounts(id) ON DELETE SET NULL, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, parent_document_id uuid REFERENCES public.crm_documents(id) ON DELETE SET NULL, owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, internal_state public.crm_doc_internal_state NOT NULL DEFAULT 'draft', external_state public.crm_doc_external_state, current_version_id uuid, confidentiality text NOT NULL DEFAULT 'internal', tags text[] NOT NULL DEFAULT '{}', created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT crm_documents_master_no_parent CHECK (doc_class <> 'master' OR parent_document_id IS NULL), CONSTRAINT crm_documents_instance_scope CHECK (doc_class <> 'customer_instance' OR account_id IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.delivery_driver_candidates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.delivery_dispatch_jobs(id) ON DELETE CASCADE, driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, score numeric(8,4) NOT NULL DEFAULT 0, distance_km numeric(8,3), eta_seconds integer, features jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (job_id, driver_id) );
CREATE TABLE IF NOT EXISTS public.driver_certifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, course_id UUID REFERENCES public.driver_courses(id) ON DELETE SET NULL, certificate_code TEXT NOT NULL UNIQUE, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.driver_training_records ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, course_id UUID NOT NULL REFERENCES public.driver_courses(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'IN_PROGRESS' CHECK (status IN ('NOT_STARTED','IN_PROGRESS','COMPLETED','FAILED')), progress_pct INT NOT NULL DEFAULT 0 CHECK (progress_pct BETWEEN 0 AND 100), score INT, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (driver_id, course_id) );
CREATE TABLE IF NOT EXISTS public.fleet_companies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES public.fleet_companies(id) ON DELETE SET NULL, entity_type public.fleet_entity_type NOT NULL DEFAULT 'COMPANY', legal_name text NOT NULL, trading_name text, registration_number text, tax_id text, country_id uuid REFERENCES public.countries(id) ON DELETE SET NULL, owner_user_id uuid, status text NOT NULL DEFAULT 'ACTIVE', metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fleet_drivers ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), fleet_id UUID NOT NULL REFERENCES public.fleets(id) ON DELETE CASCADE, driver_id UUID NOT NULL REFERENCES public.drivers(id) ON DELETE CASCADE, added_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(fleet_id, driver_id) );
CREATE TABLE IF NOT EXISTS public.fleet_vehicles ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), fleet_id UUID NOT NULL REFERENCES public.fleets(id) ON DELETE CASCADE, vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, added_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(fleet_id, vehicle_id) );
CREATE TABLE IF NOT EXISTS public.intern_cohorts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), programme_id uuid NOT NULL REFERENCES public.intern_programmes(id) ON DELETE CASCADE, name text NOT NULL UNIQUE, start_date date, end_date date, duration_weeks int, intake_size int, status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','RECRUITING','SELECTION','ONBOARDING','ACTIVE','ASSESSMENT','COMPLETION','CLOSED')), supervisor_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, target_outcomes text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.intern_tracks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), programme_id uuid NOT NULL REFERENCES public.intern_programmes(id) ON DELETE CASCADE, code text NOT NULL UNIQUE, name text NOT NULL, focus text, sequence int NOT NULL DEFAULT 0, performance_weights jsonb NOT NULL DEFAULT '{"learning":15,"productivity":20,"quality":15,"commercial":25,"operational":15,"conduct":10}'::jsonb, matching_weights jsonb NOT NULL DEFAULT '{"academic":15,"skills":15,"capability":20,"communication":10,"learning_agility":10,"problem_solving":10,"commercial":10,"digital":5,"evidence":5}'::jsonb, kpis jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_capacity_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), capacity_id uuid NOT NULL REFERENCES public.provider_capacity(id) ON DELETE CASCADE, action text NOT NULL, status_from text, status_to text, reason text, actor_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_vacancies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_no text NOT NULL UNIQUE, requisition_id uuid REFERENCES public.rec_requisitions(id) ON DELETE SET NULL, title text NOT NULL, blueprint_key text, unit_id uuid REFERENCES public.org_units(id) ON DELETE SET NULL, position_id uuid REFERENCES public.org_positions(id) ON DELETE SET NULL, hiring_manager_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, recruiter_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, employment_type text NOT NULL DEFAULT 'permanent', work_arrangement text NOT NULL DEFAULT 'onsite' CHECK (work_arrangement IN ('onsite','hybrid','remote','field')), location text, headcount integer NOT NULL DEFAULT 1 CHECK (headcount > 0), is_replacement boolean NOT NULL DEFAULT false, salary_min_cents bigint, salary_max_cents bigint, currency text NOT NULL DEFAULT 'KES', required_skills text[] NOT NULL DEFAULT '{}', preferred_skills text[] NOT NULL DEFAULT '{}', qualifications text[] NOT NULL DEFAULT '{}', competencies text[] NOT NULL DEFAULT '{}', min_years_experience numeric, responsibilities text[] NOT NULL DEFAULT '{}', kpis text[] NOT NULL DEFAULT '{}', priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','critical')), target_hire_date date, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, sla_days integer NOT NULL DEFAULT 30, approval_status text NOT NULL DEFAULT 'approved' CHECK (approval_status IN ('pending','approved','rejected')), publication_status text NOT NULL DEFAULT 'draft' CHECK (publication_status IN ('draft','published','paused','closed','archived')), published_at timestamptz, channels text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','on_hold','filled','closed','cancelled')), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.regions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES public.countries(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, parent_id uuid REFERENCES public.regions(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_id, code) );
CREATE TABLE IF NOT EXISTS public.social_provider_capabilities ( platform_slug text PRIMARY KEY REFERENCES public.social_platforms(slug) ON DELETE CASCADE, api_version text, auth_kind text NOT NULL DEFAULT 'OAUTH2', supports_text boolean NOT NULL DEFAULT false, supports_image boolean NOT NULL DEFAULT false, supports_video boolean NOT NULL DEFAULT false, supports_carousel boolean NOT NULL DEFAULT false, supports_document boolean NOT NULL DEFAULT false, supports_delete boolean NOT NULL DEFAULT false, supports_analytics boolean NOT NULL DEFAULT false, direct_publish text NOT NULL DEFAULT 'API_DEPENDENT' CHECK (direct_publish IN ('SUPPORTED','API_DEPENDENT','REQUIRES_AUDIT','NOT_SUPPORTED')), requires_audit boolean NOT NULL DEFAULT false, caption_max integer, media_max_mb integer, scheduling_owner text NOT NULL DEFAULT 'APP', cost_model text NOT NULL DEFAULT 'UNKNOWN', docs_url text, notes text, updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_documents ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, document_type_id UUID REFERENCES public.kyc_document_types(id), document_number TEXT, file_url TEXT, file_name TEXT, file_size BIGINT, file_hash TEXT, issue_date DATE, expiry_date DATE, verification_status doc_verification_status NOT NULL DEFAULT 'pending', verified_by UUID, verified_at TIMESTAMPTZ, rejection_reason TEXT, ocr_data JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.vehicle_repairs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL, accident_id uuid REFERENCES public.vehicle_accidents(id) ON DELETE SET NULL, description text NOT NULL, vendor text, started_at timestamptz, completed_at timestamptz, cost_cents bigint DEFAULT 0, status text NOT NULL DEFAULT 'OPEN', metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_contract_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, name text NOT NULL, version text NOT NULL, status text NOT NULL DEFAULT 'approved' CHECK (status IN ('draft','approved','retired')), service_provider_legal_name text NOT NULL, classification text NOT NULL DEFAULT 'private_confidential', jurisdiction text NOT NULL DEFAULT 'Republic of Kenya', scope_services text[] NOT NULL DEFAULT '{}', variables jsonb NOT NULL DEFAULT '[]'::jsonb, source_document_id uuid REFERENCES public.crm_documents(id) ON DELETE SET NULL, source_reference text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.fleet_branches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.fleet_companies(id) ON DELETE CASCADE, name text NOT NULL, region_id uuid REFERENCES public.regions(id) ON DELETE SET NULL, address text, phone text, status text NOT NULL DEFAULT 'ACTIVE', metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fleet_compliance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_company_id uuid NOT NULL REFERENCES public.fleet_companies(id) ON DELETE CASCADE, compliance_score numeric(5,2), expired_documents int NOT NULL DEFAULT 0, open_incidents int NOT NULL DEFAULT 0, last_audit_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fleet_daily_metrics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES public.fleet_companies(id) ON DELETE CASCADE, metric_date date NOT NULL, active_drivers int DEFAULT 0, active_vehicles int DEFAULT 0, trips_count int DEFAULT 0, gross_cents bigint DEFAULT 0, incidents_count int DEFAULT 0, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, metric_date) );
CREATE TABLE IF NOT EXISTS public.fleet_performance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_company_id uuid NOT NULL REFERENCES public.fleet_companies(id) ON DELETE CASCADE, metric_date date NOT NULL, active_vehicles int NOT NULL DEFAULT 0, active_drivers int NOT NULL DEFAULT 0, total_trips int NOT NULL DEFAULT 0, total_revenue_cents bigint NOT NULL DEFAULT 0, utilization_pct numeric(5,2), avg_rating numeric(3,2), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (fleet_company_id, metric_date));
CREATE TABLE IF NOT EXISTS public.fleet_regions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_company_id uuid REFERENCES public.fleet_companies(id) ON DELETE CASCADE, country_code text, region_name text NOT NULL, region_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fleet_revenue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_company_id uuid NOT NULL REFERENCES public.fleet_companies(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, gross_revenue_cents bigint NOT NULL DEFAULT 0, commission_cents bigint NOT NULL DEFAULT 0, net_payout_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.provider_bookings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_reference text NOT NULL UNIQUE, capacity_id uuid NOT NULL REFERENCES public.provider_capacity(id), enquiry_id uuid REFERENCES public.capacity_enquiries(id), provider_user_id uuid NOT NULL, customer_user_id uuid, customer_company text, customer_contact_name text, customer_email text, customer_phone text, service_from date, service_to date, qty numeric NOT NULL DEFAULT 1, unit_rate_cents bigint NOT NULL DEFAULT 0, amount_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'REQUESTED', notes text, lead_id uuid, proforma_id uuid, proforma_reference text, invoice_id uuid, invoice_reference text, is_test boolean NOT NULL DEFAULT false, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_applications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_no text NOT NULL UNIQUE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, source text NOT NULL DEFAULT 'careers_site', applied_at timestamptz NOT NULL DEFAULT now(), cover_letter text, stage text NOT NULL DEFAULT 'applied' CHECK (stage IN ('applied','received','screening','shortlisted','interview','evaluation','offer','accepted','onboarding','hired','rejected','withdrawn','talent_pool')), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','on_hold','closed')), score numeric, ai_match_score numeric, priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','critical')), recruiter_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, hiring_manager_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, next_action text, next_action_due date, stage_entered_at timestamptz NOT NULL DEFAULT now(), last_activity_at timestamptz NOT NULL DEFAULT now(), rejection_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (candidate_id, vacancy_id) );
CREATE TABLE IF NOT EXISTS public.commercial_contract_instances ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES public.commercial_contract_templates(id) ON DELETE RESTRICT, account_id uuid NOT NULL REFERENCES public.crm_accounts(id) ON DELETE CASCADE, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, document_id uuid REFERENCES public.crm_documents(id) ON DELETE SET NULL, rate_card_id uuid REFERENCES public.commercial_rate_cards(id) ON DELETE SET NULL, owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, customer_legal_name text NOT NULL, customer_variables jsonb NOT NULL DEFAULT '{}'::jsonb, selected_services text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'generated' CHECK (status IN ( 'generated','internal_review','approved','shared','under_negotiation','executed','declined','superseded')), effective_date date, contract_term text, payment_terms text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (account_id, template_id, status) DEFERRABLE INITIALLY DEFERRED );
CREATE TABLE IF NOT EXISTS public.driver_profiles_extended ( driver_id uuid PRIMARY KEY, current_stage public.lifecycle_stage NOT NULL DEFAULT 'APPLICANT', country_id uuid REFERENCES public.countries(id) ON DELETE SET NULL, region_id uuid REFERENCES public.regions(id) ON DELETE SET NULL, fleet_company_id uuid REFERENCES public.fleet_companies(id) ON DELETE SET NULL, fleet_branch_id uuid REFERENCES public.fleet_branches(id) ON DELETE SET NULL, primary_vehicle_id uuid, preferred_language text DEFAULT 'en', preferences jsonb DEFAULT '{}'::jsonb, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fleet_managers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.fleet_companies(id) ON DELETE CASCADE, branch_id uuid REFERENCES public.fleet_branches(id) ON DELETE SET NULL, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'MANAGER', permissions jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, user_id) );
CREATE TABLE IF NOT EXISTS public.intern_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid REFERENCES public.rec_candidates(id) ON DELETE SET NULL, application_id uuid REFERENCES public.rec_applications(id) ON DELETE SET NULL, staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, user_id uuid, cohort_id uuid REFERENCES public.intern_cohorts(id) ON DELETE SET NULL, track_id uuid REFERENCES public.intern_tracks(id) ON DELETE SET NULL, secondary_track_ids uuid[] NOT NULL DEFAULT '{}', full_name text NOT NULL, work_email text, institution text, programme_of_study text, qualification text, qualification_level text, year_of_study text, graduation_date date, attachment_requirement text, availability text, location text, work_arrangement text, mentor_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, supervisor_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, start_date date, expected_end_date date, actual_end_date date, status text NOT NULL DEFAULT 'APPLICANT' CHECK (status IN ('APPLICANT','ELIGIBLE','ASSESSED','SHORTLISTED','INTERVIEWED','SELECTED','OFFERED','ACCEPTED','ONBOARDING','ACTIVE','COMPLETED','WITHDRAWN','TERMINATED')), talent_level text NOT NULL DEFAULT 'APPLICANT' CHECK (talent_level IN ('APPLICANT','APPRENTICE','OPERATOR','PRODUCER','YALLA_TALENT')), conversion_status text NOT NULL DEFAULT 'NONE' CHECK (conversion_status IN ('NONE','HIGH_POTENTIAL','TALENT_REVIEW','EXTENSION','PAID_ENGAGEMENT','FIXED_TERM','PERMANENT','TALENT_POOL','NOT_PROGRESSED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, deleted_at timestamptz );
CREATE TABLE IF NOT EXISTS public.provider_booking_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.provider_bookings(id) ON DELETE CASCADE, action text NOT NULL, status_from text, status_to text, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.provider_earnings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_user_id uuid NOT NULL, booking_id uuid NOT NULL UNIQUE REFERENCES public.provider_bookings(id) ON DELETE CASCADE, booking_reference text NOT NULL, gross_cents bigint NOT NULL CHECK (gross_cents >= 0), commission_bps integer NOT NULL, commission_cents bigint NOT NULL CHECK (commission_cents >= 0), net_cents bigint NOT NULL CHECK (net_cents >= 0), currency text NOT NULL DEFAULT 'KES', state text NOT NULL DEFAULT 'ACCRUED' CHECK (state IN ('ACCRUED','PAYABLE','RESERVED','PAID','CANCELLED')), customer_paid_at timestamptz, payout_request_id uuid, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_interviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, interview_stage text NOT NULL DEFAULT 'first' CHECK (interview_stage IN ('screening_call','first','technical','panel','final','other')), interview_type text NOT NULL DEFAULT 'competency', mode text NOT NULL DEFAULT 'virtual' CHECK (mode IN ('virtual','onsite','phone')), scheduled_at timestamptz, duration_minutes integer NOT NULL DEFAULT 45, location text, meeting_link text, instructions text, objectives text[] NOT NULL DEFAULT '{}', suggested_questions text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('draft','scheduled','rescheduled','completed','cancelled','no_show')), feedback_due_at timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_offers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_no text NOT NULL UNIQUE, application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1, base_salary_cents bigint, currency text NOT NULL DEFAULT 'KES', allowances_cents bigint, benefits text[] NOT NULL DEFAULT '{}', employment_type text NOT NULL DEFAULT 'permanent', terms text, start_date date, expiry_date date, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approval','approved','sent','viewed','accepted','declined','withdrawn','expired','closed')), sent_at timestamptz, viewed_at timestamptz, responded_at timestamptz, decline_reason text, document_path text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_service_executions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_ref text NOT NULL UNIQUE, account_id uuid NOT NULL REFERENCES public.crm_accounts(id) ON DELETE CASCADE, contract_id uuid REFERENCES public.commercial_contract_instances(id) ON DELETE SET NULL, owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, service_type text NOT NULL CHECK (service_type IN ('AIRPORT_TRANSFER','STAFF_TRANSPORT','PARCEL_DELIVERY','CHARTER')), passenger_or_recipient text, origin text, destination text, scheduled_at timestamptz NOT NULL, started_at timestamptz, completed_at timestamptz, status text NOT NULL DEFAULT 'SCHEDULED' CHECK (status IN ('SCHEDULED','DISPATCHED','IN_PROGRESS','COMPLETED','DELAYED','FAILED','CANCELLED')), driver_label text, vehicle_label text, value_kes numeric(14,2) CHECK (value_kes IS NULL OR value_kes >= 0), exception_reason text, external_reference text, recorded_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_supply_driver_prospects ( id uuid primary key default gen_random_uuid(), intern_id uuid not null references public.intern_profiles(id) on delete cascade, cohort_id uuid references public.intern_cohorts(id) on delete set null, full_name text not null, phone text not null, phone_norm text generated always as (regexp_replace(coalesce(phone,''), '[^0-9]', '', 'g')) stored, location text, operating_area text, vehicle_category text, service_category text, availability text, stage text not null default 'LEAD' check (stage in ('LEAD','CONTACTED','INTERESTED','QUALIFIED','DOCUMENTS_REQUESTED','DOCUMENTS_SUBMITTED','VERIFIED','ONBOARDING','APPROVED','ACTIVATED','PRODUCTIVE','REJECTED')), documents_status text not null default 'NOT_PROVIDED' check (documents_status in ('VERIFIED','PENDING','EXPIRED','NOT_PROVIDED','NOT_APPLICABLE')), driver_record_id uuid, review_status text not null default 'SUBMITTED' check (review_status in ('SUBMITTED','ACCEPTED','RETURNED','REJECTED')), reviewed_by uuid, reviewed_at timestamptz, verified_by uuid, verified_at timestamptz, activated_at timestamptz, data_quality_score numeric, evidence_url text, notes text, is_demo boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.intern_supply_fleet_suppliers ( id uuid primary key default gen_random_uuid(), intern_id uuid not null references public.intern_profiles(id) on delete cascade, cohort_id uuid references public.intern_cohorts(id) on delete set null, supplier_name text not null, owner_name text, contact_phone text, contact_phone_norm text generated always as (regexp_replace(coalesce(contact_phone,''), '[^0-9]', '', 'g')) stored, fleet_type text, location text, operating_area text, service_category text, vehicle_count integer not null default 0 check (vehicle_count >= 0), capacity_seats integer, availability text, documentation_status text not null default 'NOT_PROVIDED' check (documentation_status in ('VERIFIED','PENDING','EXPIRED','NOT_PROVIDED','NOT_APPLICABLE')), insurance_status text not null default 'NOT_PROVIDED' check (insurance_status in ('VERIFIED','PENDING','EXPIRED','NOT_PROVIDED','NOT_APPLICABLE')), inspection_status text not null default 'NOT_PROVIDED' check (inspection_status in ('VERIFIED','PENDING','EXPIRED','NOT_PROVIDED','NOT_APPLICABLE')), driver_availability text, commercial_terms text, supplier_status text not null default 'LEAD' check (supplier_status in ('LEAD','CONTACTED','QUALIFIED','DOCUMENTS_SUBMITTED','VERIFIED','ONBOARDING','ACTIVATED','REJECTED')), activation_status text not null default 'NOT_ACTIVATED' check (activation_status in ('NOT_ACTIVATED','PENDING_ACTIVATION','ACTIVATED')), fleet_record_id uuid, review_status text not null default 'SUBMITTED' check (review_status in ('SUBMITTED','ACCEPTED','RETURNED','REJECTED')), reviewed_by uuid, reviewed_at timestamptz, verified_by uuid, verified_at timestamptz, data_quality_score numeric, evidence_url text, notes text, is_demo boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.rec_onboarding_cases ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_no text NOT NULL UNIQUE, offer_id uuid NOT NULL REFERENCES public.rec_offers(id) ON DELETE CASCADE, application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, staff_member_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, start_date date, unit_id uuid REFERENCES public.org_units(id) ON DELETE SET NULL, manager_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'preboarding' CHECK (status IN ('preboarding','in_progress','blocked','completed','cancelled')), handover_completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (offer_id) );
CREATE TABLE IF NOT EXISTS public.intern_supply_vehicles ( id uuid primary key default gen_random_uuid(), intern_id uuid not null references public.intern_profiles(id) on delete cascade, supplier_id uuid references public.intern_supply_fleet_suppliers(id) on delete cascade, cohort_id uuid references public.intern_cohorts(id) on delete set null, vehicle_type text not null, registration text, registration_norm text generated always as (upper(regexp_replace(coalesce(registration,''), '[^A-Za-z0-9]', '', 'g'))) stored, capacity integer, location text, service_category text, availability text, insurance_status text not null default 'NOT_PROVIDED' check (insurance_status in ('VERIFIED','PENDING','EXPIRED','NOT_PROVIDED','NOT_APPLICABLE')), inspection_status text not null default 'NOT_PROVIDED' check (inspection_status in ('VERIFIED','PENDING','EXPIRED','NOT_PROVIDED','NOT_APPLICABLE')), vehicle_record_id uuid, review_status text not null default 'SUBMITTED' check (review_status in ('SUBMITTED','ACCEPTED','RETURNED','REJECTED')), verified_by uuid, verified_at timestamptz, is_demo boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.provider_escalations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), escalation_ref text NOT NULL UNIQUE, route_id uuid NOT NULL REFERENCES public.provider_escalation_routes(id) ON DELETE RESTRICT, account_id uuid, signal_id uuid REFERENCES public.commercial_signals(id) ON DELETE SET NULL, execution_id uuid REFERENCES public.commercial_service_executions(id) ON DELETE SET NULL, provider_label text, summary text NOT NULL, severity text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'raised', raised_by uuid, raised_by_staff_id uuid, assigned_team text NOT NULL, due_at timestamptz NOT NULL, acknowledged_at timestamptz, acknowledged_by uuid, resolved_at timestamptz, resolved_by uuid, resolution_note text, blocks_booking boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT provider_escalations_status_chk CHECK (status IN ('raised','acknowledged','resolved','withdrawn')) );
CREATE TABLE IF NOT EXISTS public.rec_comm_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_ref text NOT NULL UNIQUE, comm_type text NOT NULL, state text NOT NULL DEFAULT 'draft', state_reason text, revision integer NOT NULL DEFAULT 1, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, application_id uuid REFERENCES public.rec_applications(id) ON DELETE CASCADE, interview_id uuid REFERENCES public.rec_interviews(id) ON DELETE SET NULL, offer_id uuid REFERENCES public.rec_offers(id) ON DELETE SET NULL, onboarding_case_id uuid REFERENCES public.rec_onboarding_cases(id) ON DELETE SET NULL, template_id uuid NOT NULL REFERENCES public.rec_letter_templates(id), template_key text NOT NULL, template_version integer NOT NULL, recipient_email text NOT NULL, recipient_name text NOT NULL, event_at timestamptz, event_timezone text NOT NULL DEFAULT 'Africa/Nairobi', business_key text NOT NULL UNIQUE, idempotency_key text NOT NULL UNIQUE, requires_approval boolean NOT NULL DEFAULT true, requested_by uuid DEFAULT auth.uid(), approved_by uuid, approved_at timestamptz, approval_note text, supersedes_id uuid REFERENCES public.rec_comm_requests(id) ON DELETE SET NULL, superseded_by_id uuid REFERENCES public.rec_comm_requests(id) ON DELETE SET NULL, queued_at timestamptz, provider_accepted_at timestamptz, delivered_at timestamptz, failed_at timestamptz, cancelled_at timestamptz, attempts integer NOT NULL DEFAULT 0, claimed_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_comm_state_chk CHECK (state IN ( 'draft','pending_approval','approved','generating','generated','queued', 'provider_accepted','delivered','failed','retry_pending','cancelled','superseded','archived')) );
CREATE TABLE IF NOT EXISTS public.rec_comm_provider_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES public.rec_comm_requests(id) ON DELETE CASCADE, provider text NOT NULL, provider_message_id text, provider_event_id text NOT NULL, event_type text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_comm_provider_event_once UNIQUE (provider, provider_event_id), CONSTRAINT rec_comm_provider_event_type_chk CHECK (event_type IN ( 'queued','accepted','sent','delivered','opened','bounced','complaint','failed','suppressed')) );
ALTER TABLE public.commercial_rate_cards ADD COLUMN IF NOT EXISTS effective_to date, ADD COLUMN IF NOT EXISTS change_summary text, ADD COLUMN IF NOT EXISTS supersedes_id uuid REFERENCES public.commercial_rate_cards(id) ON DELETE SET NULL;
