DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['air_aircraft_classes','air_airfields','charter_partner_applications','commercial_rate_cards','commercial_signals','commercial_vehicle_categories','countries','crm_accounts','delivery_dispatch_jobs','delivery_driver_scores','driver_achievement_progress','driver_achievement_tiers','driver_analytics_events','driver_application_documents','driver_application_events','driver_benefits','driver_compliance','driver_compliance_scores','driver_courses','driver_daily_metrics','driver_documents','driver_earnings_models','driver_etims_failures','driver_etims_profiles','driver_etims_retries','driver_etims_submissions','driver_etims_sync_events','driver_financial_scores','driver_housing_levy','driver_incidents','driver_insurance','driver_lifecycle_actions','driver_lifecycle_history','driver_lifecycle_stages','driver_loans','driver_locations','driver_onboarding_drafts','driver_photos','driver_reputation','driver_risk_events','driver_risk_profiles','driver_risk_rules','driver_savings','driver_scores','driver_self_reports','driver_success_stories','driver_trip_earnings','driver_vehicle_assignments','driver_verifications','driver_withdrawal_certifications','fact_drivers','fleet_driver_licences','fleets','infra_provider_actions','intern_programmes','kyc_document_types','logistics_fleet_capacity','logistics_message_providers','logistics_route_providers','provider_capacity','provider_documents','provider_escalation_routes','provider_platform_postings','provider_verification','provider_verification_events','rec_candidates','rec_letter_templates','rec_requisitions','rental_providers','service_provider_claim_events','social_platforms','vehicle_accidents','vehicle_assets','vehicle_compliance','vehicle_compliance_events','vehicle_costs','vehicle_inspections','vehicle_maintenance','vehicle_ownership_history','vehicle_service_records','air_fleet','capacity_enquiries','crm_documents','delivery_driver_candidates','driver_certifications','driver_training_records','fleet_companies','fleet_drivers','fleet_vehicles','intern_cohorts','intern_tracks','provider_capacity_events','rec_vacancies','regions','social_provider_capabilities','vehicle_documents','vehicle_repairs','commercial_contract_templates','fleet_branches','fleet_compliance','fleet_daily_metrics','fleet_performance','fleet_regions','fleet_revenue','provider_bookings','rec_applications','commercial_contract_instances','driver_profiles_extended','fleet_managers','intern_profiles','provider_booking_events','provider_earnings','rec_interviews','rec_offers','commercial_service_executions','intern_supply_driver_prospects','intern_supply_fleet_suppliers','rec_onboarding_cases','intern_supply_vehicles','provider_escalations','rec_comm_requests','rec_comm_provider_events'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[]))', t); END LOOP; END $$;
